    {
      "type": 1,
      "content": {
        "json": "## Key Performance Indicators"
      },
      "name": "heading-kpi-tiles"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let deliveredIds = ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| where DeliveryStatus == \"Delivered\"\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| distinct InternetMessageId;\nlet statusScoped = ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}));\nlet delivered = toscalar(statusScoped | where DeliveryStatus == \"Delivered\" | summarize dcount(InternetMessageId));\nlet failedBounced = toscalar(statusScoped | where DeliveryStatus in (\"Bounced\", \"Failed\") | summarize dcount(InternetMessageId));\nlet suppressed = toscalar(statusScoped | where DeliveryStatus in (\"Suppressed\", \"Quarantined\") | summarize dcount(InternetMessageId));\nlet viewed = toscalar(ACSEmailUserEngagementOperational | where TimeGenerated {TimeRange} | where EngagementType == \"View\" | where InternetMessageId in (deliveredIds) | summarize dcount(InternetMessageId));\nlet clicked = toscalar(ACSEmailUserEngagementOperational | where TimeGenerated {TimeRange} | where EngagementType == \"Click\" | where InternetMessageId in (deliveredIds) | summarize dcount(InternetMessageId));\nprint Metric = pack_array(\"Delivered\", \"Failed / Bounced\", \"Suppressed / Quarantined\", \"Viewed / Opened\", \"Clicked\"), Count = pack_array(delivered, failedBounced, suppressed, viewed, clicked)\n| mv-expand Metric to typeof(string), Count to typeof(long)",
        "size": 3,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "{Workspace}"
        ],
        "visualization": "tiles",
        "tileSettings": {
          "showBorder": true,
          "titleContent": {
            "columnMatch": "Metric",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "Count",
            "formatter": 12,
            "formatOptions": {
              "palette": "blue"
            },
            "numberFormat": {
              "unit": 17,
              "options": {
                "maximumFractionDigits": 0
              }
            }
          }
        }
      },
      "name": "kpi-tiles"
    },
    {
      "type": 1,
      "content": {
        "json": "### Delivery Status Breakdown  \n*Click a row to filter the page by that status.*"
      },
      "name": "heading-kpi-clickable-grid"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let statusRows = ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| summarize Count = dcount(InternetMessageId) by DeliveryStatus\n| project Label = DeliveryStatus, ClickValue = DeliveryStatus, Count;\nlet totalRow = ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| summarize Count = dcount(InternetMessageId)\n| project Label = \"Sent (Total) - click to reset\", ClickValue = \"value::all\", Count;\ntotalRow\n| union statusRows\n| order by iff(Label == \"Sent (Total) - click to reset\", 0, 1) asc, Count desc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "{Workspace}"
        ],
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            {
              "columnMatch": "Label",
              "formatter": 7,
              "formatterOptions": {
                "linkTarget": "Parameter",
                "parameterName": "StatusFilter",
                "parameterValue": "{ClickValue}"
              }
            },
            {
              "columnMatch": "ClickValue",
              "formatter": 5
            },
            {
              "columnMatch": "Count",
              "formatter": 12,
              "formatOptions": {
                "palette": "blue"
              },
              "numberFormat": {
                "unit": 17,
                "options": {
                  "maximumFractionDigits": 0
                }
              }
            }
          ],
          "hierarchySettings": null
        }
      },
      "name": "kpi-clickable-grid"
    },
    {
      "type": 1,
      "content": {
        "json": "### Engagement Breakdown \u2014 Delivered Messages Only  \n*Click a row to filter by engagement type. Viewed/Clicked counts are distinct messages that were actually delivered.*"
      },
      "name": "heading-engagement-kpi-grid"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let deliveredIds = ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| where DeliveryStatus == \"Delivered\"\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| distinct InternetMessageId;\nlet deliveredCount = toscalar(deliveredIds | summarize count());\nlet engagementRows = ACSEmailUserEngagementOperational\n| where TimeGenerated {TimeRange}\n| where InternetMessageId in (deliveredIds)\n| summarize Count = dcount(InternetMessageId) by EngagementType\n| project Label = case(EngagementType == \"View\", \"Viewed / Opened\", EngagementType), ClickValue = EngagementType, Count;\nlet totalRow = print Label = \"Delivered (Total) - click to reset\", ClickValue = \"value::all\", Count = deliveredCount;\ntotalRow\n| union engagementRows\n| order by iff(Label == \"Delivered (Total) - click to reset\", 0, 1) asc, Count desc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "{Workspace}"
        ],
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            {
              "columnMatch": "Label",
              "formatter": 7,
              "formatterOptions": {
                "linkTarget": "Parameter",
                "parameterName": "EngagementFilter",
                "parameterValue": "{ClickValue}"
              }
            },
            {
              "columnMatch": "ClickValue",
              "formatter": 5
            },
            {
              "columnMatch": "Count",
              "formatter": 12,
              "formatOptions": {
                "palette": "green"
              },
              "numberFormat": {
                "unit": 17,
                "options": {
                  "maximumFractionDigits": 0
                }
              }
            }
          ]
        }
      },
      "name": "engagement-kpi-grid"
    },
    {
      "type": 1,
      "content": {
