        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "{Workspace}"
        ],
        "visualization": "piechart",
        "chartSettings": {
          "xAxis": "Clinic",
          "yAxis": [
            "Count"
          ],
          "showLegend": true
        }
      },
      "name": "pie-clinic"
    },
    {
      "type": 1,
      "content": {
        "json": "### Delivery Status by Clinic"
