        "version": "KqlItem/1.0",
        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by Clinic, DeliveryStatus\n| order by Clinic asc",
        "size": 0,
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "{Workspace}"
