        "query": "ACSEmailStatusUpdateOperational\n| where TimeGenerated {TimeRange}\n| where isnotempty(RecipientId)\n| extend Clinic = strcat(SenderUsername, \"@\", SenderDomain)\n| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))\n| where ('value::all' in ({StatusFilter})) or (DeliveryStatus in ({StatusFilter}))\n| summarize Count = count() by bin(TimeGenerated, 12h), DeliveryStatus\n| order by TimeGenerated asc",
        "size": 0,
